def iterate_pages(fetch):
    cursor = None
    used = set()
    while True:
        page = fetch(cursor)
        yield from page["items"]
        cursor = page.get("next_cursor")
        if not cursor:
            return
        if cursor in used:
            raise RuntimeError(f"cursor {cursor!r} was returned twice")
        used.add(cursor)


def _split_outside(text, separator):
    parts, current, in_angle, in_quote = [], [], False, False
    for ch in text:
        if ch == '"' and not in_angle:
            in_quote = not in_quote
        elif ch == "<" and not in_quote:
            in_angle = True
        elif ch == ">" and not in_quote:
            in_angle = False
        if ch == separator and not in_angle and not in_quote:
            parts.append("".join(current))
            current = []
        else:
            current.append(ch)
    parts.append("".join(current))
    return parts


def parse_link_header(value):
    links = {}
    if not value:
        return links
    for link in _split_outside(value, ","):
        link = link.strip()
        if not link.startswith("<") or ">" not in link:
            continue
        url = link[1:link.index(">")]
        params = _split_outside(link[link.index(">") + 1:], ";")
        for param in params:
            name, eq, raw = param.partition("=")
            if not eq or name.strip().lower() != "rel":
                continue
            raw = raw.strip()
            if raw.startswith('"') and raw.endswith('"') and len(raw) >= 2:
                raw = raw[1:-1]
            for rel in raw.split():
                links.setdefault(rel.lower(), url)
    return links

