import itertools

class Pages:
    def __init__(self, pages):
        self.pages = pages
        self.calls = []
    def __call__(self, cursor):
        self.calls.append(cursor)
        return self.pages[cursor]

@test("all items across pages")
def _():
    f = Pages({None: {"items": [1, 2], "next_cursor": "c1"}, "c1": {"items": [3], "next_cursor": "c2"}, "c2": {"items": [4, 5], "next_cursor": None}})
    check_eq(list(iterate_pages(f)), [1, 2, 3, 4, 5])
    check_eq(f.calls, [None, "c1", "c2"])

@test("empty pages and an empty cursor")
def _():
    f = Pages({None: {"items": [], "next_cursor": "a"}, "a": {"items": ["x"], "next_cursor": ""}})
    check_eq(list(iterate_pages(f)), ["x"])
    check_eq(list(iterate_pages(Pages({None: {"items": [], "next_cursor": None}}))), [])

@test("pages are fetched lazily")
def _():
    f = Pages({None: {"items": [1, 2], "next_cursor": "c1"}, "c1": {"items": [3, 4], "next_cursor": "c2"}, "c2": {"items": [5], "next_cursor": None}})
    gen = iterate_pages(f)
    check_eq(f.calls, [])
    check_eq(list(itertools.islice(gen, 3)), [1, 2, 3])
    check_eq(f.calls, [None, "c1"])

@test("loop protection")
def _():
    f = Pages({None: {"items": [1], "next_cursor": "a"}, "a": {"items": [2], "next_cursor": "b"}, "b": {"items": [3], "next_cursor": "a"}})
    gen = iterate_pages(f)
    check_eq([next(gen), next(gen), next(gen)], [1, 2, 3])
    check_raises(RuntimeError, next, gen)

@test("a typical Link header")
def _():
    h = '<https://api.example.com/books?page=3>; rel="next", <https://api.example.com/books?page=9>; rel="last"'
    check_eq(parse_link_header(h), {"next": "https://api.example.com/books?page=3", "last": "https://api.example.com/books?page=9"})

@test("awkward but valid headers")
def _():
    h = '<https://h/x?a=1,2>; title="a, b; c"; REL="next prev",<https://h/y>;rel=first, <https://h/z>; rel="next"'
    check_eq(parse_link_header(h), {"next": "https://h/x?a=1,2", "prev": "https://h/x?a=1,2", "first": "https://h/y"})
    check_eq(parse_link_header('<https://h/a>; rel="Next"'), {"next": "https://h/a"})
    check_eq(parse_link_header('<https://h/a>; title="no rel"'), {})
    check_eq(parse_link_header(""), {})
    check_eq(parse_link_header(None), {})

